import { useEffect, useRef, useState } from "react";
import DOMPurify from "dompurify";
import "./App.css";
import CanvasArea from "./CanvasArea";
import SiteFooter from "./SiteFooter";
import SiteHeader from "./SiteHeader";
import type { Availability, PortfolioTab } from "./types";
type ModelMonitor = {
  addEventListener: (
    type: "downloadprogress",
    listener: (event: { loaded: number }) => void,
  ) => void;
};
type PromptSession = {
  prompt: (
    input: string | Array<{ role: string; content: string }>,
    options?: { signal?: AbortSignal; responseConstraint?: object },
  ) => Promise<string>;
  promptStreaming: (
    input: string,
    options?: { signal?: AbortSignal },
  ) => ReadableStream<string>;
  destroy: () => void;
};
type LanguageModelApi = {
  availability: (options: object) => Promise<Availability>;
  create: (options?: {
    initialPrompts?: Array<{ role: string; content: string }>;
    monitor?: (monitor: ModelMonitor) => void;
  }) => Promise<PromptSession>;
};

declare global {
  interface Window {
    LanguageModel?: LanguageModelApi;
  }
}

const modelOptions = {
  expectedInputs: [{ type: "text", languages: ["en"] }],
  expectedOutputs: [{ type: "text", languages: ["en"] }],
};
const tabSchema = {
  type: "object",
  properties: {
    tabs: {
      type: "array",
      minItems: 3,
      maxItems: 3,
      items: {
        type: "object",
        properties: {
          id: { type: "string" },
          label: { type: "string" },
          prompt: { type: "string" },
        },
        required: ["id", "label", "prompt"],
      },
    },
  },
  required: ["tabs"],
};
const fallbackTabs: PortfolioTab[] = [
  {
    id: "systems",
    label: "Systems at scale",
    prompt: "Focus on professional engineering experience and impact.",
  },
  {
    id: "experiments",
    label: "Side experiments",
    prompt:
      "Focus on personal projects, product work, and technical curiosity.",
  },
  {
    id: "outside",
    label: "Outside the stack",
    prompt:
      "Focus on leadership, interests, and the ideas behind the work.",
  },
];
const fallbackCanvas = `<article class="landing-canvas"><p class="eyebrow">Luke's website</p><h1>Click a tab above.</h1><p>And get your browser AI to work.</p></article>`;
const systemPrompt = `You are the local portfolio editor for Luke Cheng. The complete source of truth is the portfolio markdown supplied below. Never invent facts, companies, dates, metrics, technologies, links, or responsibilities. You may make the presentation surprising and editorial, but every factual claim must be traceable to the source.

For canvas requests, return only semantic HTML and inline style attributes for layout. Never return markdown, code fences, script, style, iframe, form controls, SVG, images, event handlers, or javascript URLs. Use only article, aside, div, section, header, h1, h2, h3, p, ul, ol, li, a, strong, em, small, time, dl, dt, and dd. Make the composition feel like a thoughtful personal website, not a generic resume.

Structure every canvas response in exactly this order: Summary, Why, then How. Use a clear heading for each section. Summary states the main point or answer. Why explains the relevant context, reasoning, or significance. How explains the implementation, process, or specific evidence from the portfolio. When a section is not applicable, keep it concise rather than inventing information.

Portfolio source:
`;

function getErrorMessage(error: unknown) {
  return error instanceof Error ? error.message : String(error);
}

function sanitizeCanvas(html: string) {
  const withoutFences = html
    .replace(/^\s*```(?:html)?\s*/i, "")
    .replace(/\s*```\s*$/i, "");
  return DOMPurify.sanitize(withoutFences, {
    ALLOWED_TAGS: [
      "article",
      "aside",
      "div",
      "section",
      "header",
      "h1",
      "h2",
      "h3",
      "p",
      "ul",
      "ol",
      "li",
      "a",
      "strong",
      "em",
      "small",
      "time",
      "dl",
      "dt",
      "dd",
      "br",
    ],
    ALLOWED_ATTR: ["class", "href", "target", "rel", "style"],
    FORBID_ATTR: ["onclick", "onload", "onerror"],
  });
}

function App() {
  const [portfolio, setPortfolio] = useState("");
  const [tabs, setTabs] = useState(fallbackTabs);
  const [activeTab, setActiveTab] = useState(fallbackTabs[0].id);
  const [canvas, setCanvas] = useState(fallbackCanvas);
  const [question, setQuestion] = useState("");
  const [availability, setAvailability] = useState<Availability | "checking">(
    "checking",
  );
  const [isReady, setIsReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState("");
  const sessionRef = useRef<PromptSession | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const createSession = async (source: string) => {
    if (!window.LanguageModel) return;
    try {
      const session = await window.LanguageModel.create({
        initialPrompts: [
          { role: "system", content: `${systemPrompt}\n${source}` },
        ],
        monitor: (monitor) =>
          monitor.addEventListener("downloadprogress", (event) =>
            setProgress(event.loaded),
          ),
      });
      sessionRef.current = session;
      setIsReady(true);
      setAvailability("available");
      const result = await session.prompt(
        "Create exactly three concise navigation tabs for this portfolio. Return JSON matching the requested schema.",
        { responseConstraint: tabSchema },
      );
      const parsed = JSON.parse(result) as { tabs?: PortfolioTab[] };
      if (parsed.tabs?.length === 3) setTabs(parsed.tabs);
    } catch (error) {
      console.error(error);
      setError(getErrorMessage(error));
    }
  };

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      try {
        const [source, status] = await Promise.all([
          fetch("/portfolio.md").then((response) => response.text()),
          window.LanguageModel?.availability(modelOptions) ??
            Promise.resolve("unavailable" as const),
        ]);
        if (cancelled) return;
        setPortfolio(source);
        setAvailability(status);
        if (status === "available") await createSession(source);
      } catch (error) {
        console.error(error);
        if (!cancelled) setError(getErrorMessage(error));
      }
    };
    void boot();
    return () => {
      cancelled = true;
      abortRef.current?.abort();
      sessionRef.current?.destroy();
    };
  }, []);

  const activateModel = () => {
    if (portfolio) {
      setError("");
      setAvailability("downloading");
      void createSession(portfolio);
    }
  };
  const generateCanvas = async (tab: PortfolioTab, requestedQuestion = "") => {
    const session = sessionRef.current;
    if (!session) return;
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setIsGenerating(true);
    setError("");
    let output = "";
    try {
      const request = requestedQuestion
        ? `Answer the visitor's question directly: “${requestedQuestion}” Use the portfolio source as your only evidence. The selected lens is “${tab.label}”, which may influence emphasis but must not turn the answer into a generic resume. Explain the relevant connections, reasoning, or tradeoffs when the source supports them. Do not merely list experience. Present the answer as a thoughtful, focused portfolio canvas in semantic HTML. Return semantic HTML only.`
        : `Compose the main portfolio canvas for the view “${tab.label}”. ${tab.prompt} Use a clear hierarchy, one unusual but usable layout, and only facts from the source. Return semantic HTML only.`;
      for await (const chunk of session.promptStreaming(request, {
        signal: controller.signal,
      })) {
        output += chunk;
        setCanvas(sanitizeCanvas(output));
      }
    } catch (generationError) {
      if ((generationError as Error).name !== "AbortError") {
        console.error(generationError);
        setError(getErrorMessage(generationError));
      }
    } finally {
      setIsGenerating(false);
    }
  };
  const handleTabChange = (tab: PortfolioTab) => {
    setActiveTab(tab.id);
    void generateCanvas(tab);
  };
  const handleQuestion = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedQuestion = question.trim();
    if (!trimmedQuestion) return;
    if (!isReady) {
      setError("Local AI is not ready yet. Your question is ready when Chrome AI becomes available.");
      return;
    }
    setQuestion("");
    const tab = tabs.find((item) => item.id === activeTab) ?? tabs[0];
    void generateCanvas(tab, trimmedQuestion);
  };
  const statusLabel =
    availability === "checking"
      ? "Checking local model"
      : availability === "available" && isReady
        ? "Local AI ready"
        : availability === "downloading"
          ? "Downloading local model"
          : availability === "unavailable"
            ? "Chrome AI unavailable"
            : "Local model available";

  return (
    <div className={`site-shell ${isGenerating ? "is-generating" : ""}`}>
      <SiteHeader
        tabs={tabs}
        activeTab={activeTab}
        question={question}
        statusLabel={statusLabel}
        isReady={isReady}
        isGenerating={isGenerating}
        onTabChange={handleTabChange}
        onQuestionChange={setQuestion}
        onQuestion={handleQuestion}
        onStop={() => abortRef.current?.abort()}
        onReset={() => window.location.reload()}
      />
      <CanvasArea
        isReady={isReady}
        isGenerating={isGenerating}
        availability={availability}
        progress={progress}
        canvas={canvas}
        error={error}
        onActivate={activateModel}
        onDismissError={() => setError("")}
      />
      <SiteFooter />
    </div>
  );
}

export default App;

@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;1,500&display=swap");
:root {
  color-scheme: light dark;
  --ink: #171917;
  --muted: #6d7369;
  --paper: #f1f0e9;
  --line: #c8c9bd;
  --acid: #d9ff4f;
  --coral: #ff6b4a;
  --mono: "DM Mono", monospace;
  --sans: "Manrope", sans-serif;
  --serif: "Playfair Display", serif;
}
@media (prefers-color-scheme: dark) {
  :root {
    --ink: #f0f0e8;
    --muted: #a5aa9e;
    --paper: #171917;
    --line: #41453d;
    --acid: #d9ff4f;
    --coral: #ff8064;
  }
}
* {
  box-sizing: border-box;
}
body {
  color: var(--ink);
  background: var(--paper);
  font: 15px/1.6 var(--sans);
}
button,
input {
  font: inherit;
}
button {
  color: inherit;
  cursor: pointer;
}
.site-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: auto;
  padding: 0 4vw 94px;
}
.site-shell.is-generating {
  cursor: wait;
}
.site-shell.is-generating button,
.site-shell.is-generating input {
  cursor: wait;
}
.site-shell.is-generating .exit-button {
  cursor: pointer;
}
.site-header {
  padding: 32px 0 0;
  border-bottom: 1px solid var(--ink);
}
.header-top,
.header-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.header-top {
  min-height: 54px;
}
.header-bottom {
  gap: 30px;
  padding: 30px 0 18px;
}
.identity {
  flex: 0 0 auto;
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}
.identity:hover strong,
.identity:focus-visible strong {
  color: var(--coral);
}
.eyebrow,
.model-status,
.tab-nav span {
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.identity strong {
  display: block;
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.05em;
}
.identity-button {
  border: 0;
  background: transparent;
  color: inherit;
  font: 600 20px var(--sans);
  letter-spacing: -0.05em;
  padding: 0;
}
.identity-button:hover,
.identity-button:focus-visible {
  color: var(--coral);
}
.model-status {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 10px;
}
.status-dot,
.pulse {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--coral);
}
.status-dot.ready,
.status-dot.ready {
  background: #60a436;
}
.question-bar {
  display: flex;
  align-items: center;
  flex: 1;
  max-width: none;
}
.prompt-symbol {
  color: var(--coral);
  font: 24px var(--serif);
  padding-right: 10px;
}
.question-bar input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  padding: 15px 0;
  color: var(--ink);
}
.question-bar input::placeholder {
  color: var(--muted);
}
.primary-button {
  border: 0;
  background: var(--ink);
  color: var(--acid);
  padding: 9px 13px;
  font: 11px var(--mono);
  text-transform: uppercase;
}
.submit-button {
  display: grid;
  flex: 0 0 34px;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 0;
  background: var(--ink);
  color: var(--acid);
  font: 20px/1 var(--mono);
}
@media (prefers-color-scheme: dark) {
  .submit-button {
    background: var(--paper);
    color: var(--acid);
  }
}
.submit-button:disabled {
  cursor: default;
  opacity: 0.45;
}
.return-icon {
  position: relative;
  display: block;
  width: 15px;
  height: 13px;
  border-bottom: 2px solid currentColor;
  border-left: 2px solid currentColor;
}
.return-icon::after {
  position: absolute;
  right: -1px;
  bottom: -3px;
  width: 7px;
  height: 7px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  content: "";
  transform: rotate(-45deg);
}
.exit-button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid var(--coral);
  background: var(--coral);
  color: var(--paper);
  font: 24px/1 var(--sans);
}
.exit-button:hover,
.exit-button:focus-visible {
  background: var(--ink);
  color: var(--coral);
  outline: 2px solid var(--coral);
  outline-offset: 2px;
}
.question-bar button:disabled,
.tab-nav button:disabled {
  cursor: default;
  opacity: 0.45;
}
.tab-nav {
  display: flex;
  align-items: end;
  gap: 26px;
  overflow-x: auto;
}
.tab-nav button {
  position: relative;
  border: 0;
  background: transparent;
  padding: 0 0 14px;
  text-align: left;
  white-space: nowrap;
}
.tab-nav button span {
  margin-right: 10px;
  color: var(--coral);
}
.tab-nav button.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 3px;
  background: var(--coral);
  content: "";
}
.canvas-wrap {
  position: relative;
  padding: 112px 0 80px;
}
.ai-gate {
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 20px;
  min-height: calc(100svh - 230px);
  margin-bottom: 0;
  padding: 7vh 8vw;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 15px;
}
.ai-gate h2 {
  max-width: 900px;
  margin: 0;
  color: var(--ink);
  font-size: clamp(48px, 8vw, 128px);
  font-weight: 500;
  line-height: 0.92;
  letter-spacing: -0.08em;
}
.ai-gate p { max-width: 560px; margin: 0; }
.ai-gate .eyebrow { color: var(--coral); }
.primary-button {
  margin-left: auto;
}
.progress-track {
  flex: 0 1 180px;
  height: 5px;
  background: var(--line);
}
.progress-track span {
  display: block;
  height: 100%;
  background: var(--coral);
  transition: width 0.3s ease;
}
.error-message {
  color: var(--coral) !important;
}
.landing-canvas {
  min-height: 54vh;
  padding-top: 15vh;
  text-align: center;
}
.landing-canvas h1 {
  margin: 20px 0 10px;
  font-size: clamp(44px, 8vw, 108px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.08em;
}
.landing-canvas p:last-child {
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.generated-canvas {
  min-height: 520px;
  transition: opacity 0.25s ease;
}
.generated-canvas.is-generating {
  opacity: 0.62;
}
.canvas-intro {
  max-width: 900px;
}
.eyebrow {
  color: var(--muted);
}
.canvas-intro h1 {
  max-width: 850px;
  margin: 22px 0 26px;
  font-size: clamp(54px, 8vw, 126px);
  font-weight: 500;
  line-height: 0.91;
  letter-spacing: -0.08em;
}
.canvas-intro h1 em {
  color: var(--coral);
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.05em;
}
.lead {
  max-width: 600px;
  color: var(--muted);
  font-size: 19px;
}
.canvas-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 12vw;
  max-width: 980px;
  margin: 130px 0 0 auto;
}
.feature-block {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}
.feature-block h2 {
  max-width: 500px;
  margin: 28px 0 20px;
  font-size: clamp(30px, 4vw, 58px);
  line-height: 0.98;
  letter-spacing: -0.06em;
}
.feature-block p:not(.eyebrow) {
  max-width: 550px;
  color: var(--muted);
}
.margin-note {
  align-self: end;
  border-top: 1px solid var(--coral);
  padding-top: 11px;
  color: var(--muted);
  font: 12px/1.45 var(--mono);
}
.margin-note span {
  display: block;
  margin-bottom: 20px;
  color: var(--coral);
}
.signal-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 120px;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  padding: 22px 0;
}
.signal-row div {
  display: flex;
  flex-direction: column;
}
.signal-row strong {
  font-size: clamp(32px, 4vw, 58px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.06em;
}
.signal-row span {
  margin-top: 9px;
  color: var(--muted);
  font: 11px var(--mono);
  text-transform: uppercase;
}
.inline-error {
  position: fixed;
  right: 4vw;
  bottom: 78px;
  z-index: 2;
  padding: 9px 12px;
  background: var(--ink);
  color: var(--paper);
  font: 11px var(--mono);
}
.inline-error button {
  margin-left: 12px;
  border: 0;
  border-bottom: 1px solid currentColor;
  background: transparent;
  color: var(--acid);
  font: inherit;
}
.pulse {
  animation: pulse 1s infinite;
}
.site-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  position: fixed;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 3;
  padding: 13px 4vw;
  border-top: 1px solid var(--ink);
  background: var(--paper);
  font-size: 11px;
}
.site-footer p {
  margin: 0;
  color: var(--muted);
}
.footer-links {
  display: flex;
  gap: 18px;
  white-space: nowrap;
}
.site-footer a {
  color: var(--ink);
  text-decoration: none;
}
.site-footer a:hover {
  color: var(--coral);
}
@keyframes pulse {
  50% {
    opacity: 0.25;
  }
}
@media (max-width: 700px) {
  .site-shell {
    padding: 0 20px 118px;
  }
  .site-header {
    padding-top: 22px;
  }
  .header-top { align-items: flex-start; flex-direction: column; gap: 24px; }
  .header-bottom { align-items: stretch; flex-direction: column-reverse; gap: 12px; padding-top: 28px; }
  .ai-info-trigger span:last-child { display: none; }
  .model-status {
    align-self: flex-start;
  }
  .tab-nav {
    gap: 20px;
  }
  .canvas-wrap {
    padding-top: 62px;
  }
  .ai-gate {
    min-height: calc(100svh - 250px);
    padding: 8vh 0;
    gap: 16px;
  }
  .progress-track {
    flex-basis: 100%;
  }
  .primary-button { margin-left: 0; }
  .landing-canvas { min-height: 62vh; padding-top: 18vh; }
  .canvas-intro h1 {
    font-size: clamp(48px, 15vw, 90px);
  }
  .canvas-grid {
    display: block;
    margin-top: 80px;
  }
  .margin-note {
    margin-top: 35px;
  }
  .signal-row {
    margin-top: 75px;
  }
  .signal-row strong {
    font-size: 35px;
  }
  .site-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
    padding: 12px 20px;
  }
  .inline-error {
    right: 20px;
    bottom: 103px;
  }
}

