import { useEffect, useState } from "react";
import DOMPurify from "dompurify";
import { marked } from "marked";
import SiteFooter from "./SiteFooter";
import "./PortfolioPage.css";

function PortfolioPage() {
  const [content, setContent] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    fetch("/portfolio.md")
      .then((response) => {
        if (!response.ok) throw new Error("The portfolio could not be loaded.");
        return response.text();
      })
      .then((markdown) =>
        setContent(DOMPurify.sanitize(marked.parse(markdown) as string)),
      )
      .catch((loadError) => setError(loadError.message));
  }, []);

  return (
    <div className="portfolio-page">
      <header className="portfolio-page-header">
        <a href="/" className="portfolio-back-link">
          Back to portfolio ↙
        </a>
        <span className="eyebrow">Luke Cheng / Resume</span>
      </header>
      {error ? (
        <p className="error-message">{error}</p>
      ) : (
        <article
          className="portfolio-markdown"
          dangerouslySetInnerHTML={{ __html: content }}
        />
      )}
      <SiteFooter />
    </div>
  );
}

export default PortfolioPage;

.portfolio-page {
  max-width: 1040px;
  min-height: 100svh;
  margin: auto;
  padding: 32px 4vw 120px;
}

.portfolio-page-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 18px;
}

.portfolio-back-link {
  color: var(--coral);
  font: 11px var(--mono);
  text-decoration: none;
  text-transform: uppercase;
}

.portfolio-markdown {
  max-width: 820px;
  margin: 80px auto 0;
}

.portfolio-markdown h1 {
  margin: 0 0 60px;
  font-size: clamp(48px, 8vw, 112px);
  font-weight: 500;
  line-height: 0.92;
  letter-spacing: -0.08em;
}

.portfolio-markdown h2 {
  margin: 72px 0 24px;
  border-top: 1px solid var(--ink);
  padding-top: 12px;
  font-size: 12px;
  font-family: var(--mono);
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.portfolio-markdown h3 {
  margin: 40px 0 8px;
  font-size: clamp(22px, 3vw, 34px);
  font-weight: 500;
  line-height: 1.05;
  letter-spacing: -0.05em;
}

.portfolio-markdown p,
.portfolio-markdown li {
  color: var(--muted);
}

.portfolio-markdown blockquote {
  margin: 0 0 18px;
  color: var(--coral);
  font: 12px var(--mono);
}

.portfolio-markdown ul {
  padding-left: 20px;
}

.portfolio-markdown li {
  margin: 9px 0;
}

.portfolio-markdown a {
  color: var(--ink);
}

@media (max-width: 700px) {
  .portfolio-page {
    padding: 22px 20px 140px;
  }

  .portfolio-page-header {
    align-items: flex-start;
    flex-direction: column-reverse;
    gap: 12px;
  }

  .portfolio-markdown {
    margin-top: 54px;
  }
}

import type { FormEvent } from "react";

export type Availability =
  | "available"
  | "downloadable"
  | "downloading"
  | "unavailable";

export type PortfolioTab = {
  id: string;
  label: string;
  prompt: string;
};

export type ModelMonitor = {
  addEventListener: (
    type: "downloadprogress",
    listener: (event: { loaded: number }) => void,
  ) => void;
};

export type PromptSession = {
  prompt: (
    input: string | Array<{ role: string; content: string }>,
    options?: { signal?: AbortSignal; responseConstraint?: object },
  ) => Promise<string>;
  promptStreaming: (
    input: string,
    options?: { signal?: AbortSignal },
  ) => ReadableStream<string>;
  destroy: () => void;
};

export type LanguageModelApi = {
  availability: (options: object) => Promise<Availability>;
  create: (options?: {
    initialPrompts?: Array<{ role: string; content: string }>;
    monitor?: (monitor: ModelMonitor) => void;
  }) => Promise<PromptSession>;
};

export type SiteHeaderProps = {
  tabs: PortfolioTab[];
  activeTab: string;
  question: string;
  statusLabel: string;
  isReady: boolean;
  isGenerating: boolean;
  onTabChange: (tab: PortfolioTab) => void;
  onQuestionChange: (question: string) => void;
  onQuestion: (event: FormEvent<HTMLFormElement>) => void;
  onStop: () => void;
  onReset: () => void;
};

export type CanvasAreaProps = {
  isReady: boolean;
  isGenerating: boolean;
  availability: Availability | "checking";
  progress: number;
  canvas: string;
  error: string;
  onActivate: () => void;
  onDismissError: () => void;
};

export type ErrorFallbackProps = {
  availability: Availability | "checking";
  progress: number;
  error: string;
  onActivate: () => void;
};

declare global {
  interface Window {
    LanguageModel?: LanguageModelApi;
  }
}

import { useEffect, useRef, useState } from "react";
import DOMPurify from "dompurify";
import "./App.css";
import CanvasArea from "./CanvasArea";
import SiteFooter from "./SiteFooter";
import SiteHeader from "./SiteHeader";
import type { Availability, PortfolioTab, PromptSession } from "./types";

const modelOptions = {
  expectedInputs: [{ type: "text", languages: ["en"] }],
  expectedOutputs: [{ type: "text", languages: ["en"] }],
};
const tabSchema = {
  type: "object",
  properties: {
    tabs: {
      type: "array",
      minItems: 3,
      maxItems: 5,
      items: {
        type: "object",
        properties: {
          id: { type: "string" },
          label: { type: "string" },
          prompt: { type: "string" },
        },
        required: ["id", "label", "prompt"],
      },
    },
  },
  required: ["tabs"],
};
const fallbackTabs: PortfolioTab[] = [
  {
    id: "systems",
    label: "Systems at scale",
    prompt: "Focus on professional engineering experience and impact.",
  },
  {
    id: "experiments",
    label: "Side experiments",
    prompt:
      "Focus on personal projects, product work, and technical curiosity.",
  },
  {
    id: "outside",
    label: "Outside the stack",
    prompt: "Focus on leadership, interests, and the ideas behind the work.",
  },
];
const fallbackCanvas = `<article class="landing-canvas"><p class="eyebrow">Luke's website</p><h1>Click a tab above.</h1><p>And get your browser AI to work.</p></article>`;
const systemPrompt = `You are the local portfolio editor for Luke Cheng. The complete source of truth is the portfolio markdown supplied below. Never invent facts, companies, dates, metrics, technologies, links, or responsibilities. You may make the presentation surprising and editorial, but every factual claim must be traceable to the source.

For canvas requests, return only semantic HTML and inline style attributes for layout. Never return markdown, code fences, script, style, iframe, form controls, SVG, images, event handlers, or javascript URLs. Use only article, aside, div, section, header, h1, h2, h3, p, ul, ol, li, a, strong, em, small, time, dl, dt, and dd. Make the composition feel like a thoughtful personal website, not a generic resume.

Structure every canvas response in exactly this order: Summary, Why, then How. Use a clear heading for each section. Summary states the main point or answer. Why explains the relevant context, reasoning, or significance. How explains the implementation, process, or specific evidence from the portfolio. When a section is not applicable, keep it concise rather than inventing information.

Portfolio source:
`;

function getErrorMessage(error: unknown) {
  return error instanceof Error ? error.message : String(error);
}

function sanitizeCanvas(html: string) {
  const withoutFences = html
    .replace(/^\s*```(?:html)?\s*/i, "")
    .replace(/\s*```\s*$/i, "");
  return DOMPurify.sanitize(withoutFences, {
    ALLOWED_TAGS: [
      "article",
      "aside",
      "div",
      "section",
      "header",
      "h1",
      "h2",
      "h3",
      "p",
      "ul",
      "ol",
      "li",
      "a",
      "strong",
      "em",
      "small",
      "time",
      "dl",
      "dt",
      "dd",
      "br",
    ],
    ALLOWED_ATTR: ["class", "href", "target", "rel", "style"],
    FORBID_ATTR: ["onclick", "onload", "onerror"],
  });
}

function App() {
  const [portfolio, setPortfolio] = useState("");
  const [tabs, setTabs] = useState(fallbackTabs);
  const [activeTab, setActiveTab] = useState(fallbackTabs[0].id);
  const [canvas, setCanvas] = useState(fallbackCanvas);
  const [question, setQuestion] = useState("");
  const [availability, setAvailability] = useState<Availability | "checking">(
    "checking",
  );
  const [isReady, setIsReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState("");
  const sessionRef = useRef<PromptSession | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const createSession = async (source: string) => {
    if (!window.LanguageModel) return;
    try {
      const session = await window.LanguageModel.create({
        initialPrompts: [
          { role: "system", content: `${systemPrompt}\n${source}` },
        ],
        monitor: (monitor) =>
          monitor.addEventListener("downloadprogress", (event) =>
            setProgress(event.loaded),
          ),
      });
      sessionRef.current = session;
      setIsReady(true);
      setAvailability("available");
      const result = await session.prompt(
        "Create exactly three concise navigation tabs for this portfolio. Return JSON matching the requested schema.",
        { responseConstraint: tabSchema },
      );
      const parsed = JSON.parse(result) as { tabs?: PortfolioTab[] };
      if (parsed.tabs?.length === 3) setTabs(parsed.tabs);
    } catch (error) {
      console.error(error);
      setError(getErrorMessage(error));
    }
  };

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      try {
        const [source, status] = await Promise.all([
          fetch("/portfolio.md").then((response) => response.text()),
          window.LanguageModel?.availability(modelOptions) ??
            Promise.resolve("unavailable" as const),
        ]);
        if (cancelled) return;
        setPortfolio(source);
        setAvailability(status);
        if (status === "available") await createSession(source);
      } catch (error) {
        console.error(error);
        if (!cancelled) setError(getErrorMessage(error));
      }
    };
    void boot();
    return () => {
      cancelled = true;
      abortRef.current?.abort();
      sessionRef.current?.destroy();
    };
  }, []);

  const activateModel = () => {
    if (portfolio) {
      setError("");
      setAvailability("downloading");
      void createSession(portfolio);
    }
  };
  const generateCanvas = async (tab: PortfolioTab, requestedQuestion = "") => {
    const session = sessionRef.current;
    if (!session) return;
    abortRef.current?.abort();
    const controller = new AbortController();
    abortRef.current = controller;
    setIsGenerating(true);
    setError("");
    let output = "";
    try {
      const request = requestedQuestion
        ? `Answer the visitor's question directly: “${requestedQuestion}” Use the portfolio source as your only evidence. The selected lens is “${tab.label}”, which may influence emphasis but must not turn the answer into a generic resume. Explain the relevant connections, reasoning, or tradeoffs when the source supports them. Do not merely list experience. Present the answer as a thoughtful, focused portfolio canvas in semantic HTML. Return semantic HTML only.`
        : `Compose the main portfolio canvas for the view “${tab.label}”. ${tab.prompt} Use a clear hierarchy, one unusual but usable layout, and only facts from the source. Return semantic HTML only.`;
      for await (const chunk of session.promptStreaming(request, {
        signal: controller.signal,
      })) {
        output += chunk;
        setCanvas(sanitizeCanvas(output));
      }
    } catch (generationError) {
      if ((generationError as Error).name !== "AbortError") {
        console.error(generationError);
        setError(getErrorMessage(generationError));
      }
    } finally {
      setIsGenerating(false);
    }
  };
  const handleTabChange = (tab: PortfolioTab) => {
    setActiveTab(tab.id);
    void generateCanvas(tab);
  };
  const handleQuestion = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedQuestion = question.trim();
    if (!trimmedQuestion) return;
    if (!isReady) {
      setError(
        "Local AI is not ready yet. Your question is ready when Chrome AI becomes available.",
      );
      return;
    }
    setQuestion("");
    const tab = tabs.find((item) => item.id === activeTab) ?? tabs[0];
    void generateCanvas(tab, trimmedQuestion);
  };
  const statusLabel =
    availability === "checking"
      ? "Checking local model"
      : availability === "available" && isReady
        ? "Local AI ready"
        : availability === "downloading"
          ? "Downloading local model"
          : availability === "unavailable"
            ? "Chrome AI unavailable"
            : "Local model available";

  return (
    <div className={`site-shell ${isGenerating ? "is-generating" : ""}`}>
      <SiteHeader
        tabs={tabs}
        activeTab={activeTab}
        question={question}
        statusLabel={statusLabel}
        isReady={isReady}
        isGenerating={isGenerating}
        onTabChange={handleTabChange}
        onQuestionChange={setQuestion}
        onQuestion={handleQuestion}
        onStop={() => abortRef.current?.abort()}
        onReset={() => window.location.reload()}
      />
      <CanvasArea
        isReady={isReady}
        isGenerating={isGenerating}
        availability={availability}
        progress={progress}
        canvas={canvas}
        error={error}
        onActivate={activateModel}
        onDismissError={() => setError("")}
      />
      <SiteFooter />
    </div>
  );
}

export default App;

import type { SiteHeaderProps } from "./types";

import AssistantIcon from "@mui/icons-material/Assistant";
import CancelScheduleSendIcon from "@mui/icons-material/CancelScheduleSend";
function SiteHeader({
  tabs,
  activeTab,
  question,
  statusLabel,
  isReady,
  isGenerating,
  onTabChange,
  onQuestionChange,
  onQuestion,
  onStop,
  onReset,
}: SiteHeaderProps) {
  return (
    <header className="site-header">
      <div className="header-top">
        <button className="identity" type="button" onClick={onReset}>
          <strong>Luke Cheng</strong>
        </button>
        <nav className="tab-nav" aria-label="Portfolio views">
          {tabs.map((tab, index) => (
            <button
              key={tab.id}
              className={activeTab === tab.id ? "active" : ""}
              type="button"
              onClick={() => onTabChange(tab)}
              disabled={!isReady || isGenerating}
            >
              <span>0{index + 1}</span>
              {tab.label}
            </button>
          ))}
        </nav>
      </div>
      <div className="header-bottom">
        <form className="question-bar" onSubmit={onQuestion}>
          <span className="prompt-symbol">↳</span>
          <input
            value={question}
            onChange={(event) => onQuestionChange(event.target.value)}
            placeholder="Ask the portfolio a question..."
            aria-label="Ask the portfolio a question"
            disabled={isGenerating}
          />
          <span className="model-status">
            <span className={`status-dot ${isReady ? "ready" : ""}`} />
            {statusLabel}
          </span>
          {isGenerating ? (
            <button
              className="exit-button"
              type="button"
              aria-label="Stop generating"
              title="Stop generating"
              onClick={onStop}
            >
              <span aria-hidden="true">
                <CancelScheduleSendIcon />
              </span>
            </button>
          ) : (
            <button
              className="submit-button"
              type="submit"
              aria-label="Ask question"
              disabled={!isReady || !question.trim()}
            >
              <AssistantIcon />
            </button>
          )}
        </form>
      </div>
    </header>
  );
}

export default SiteHeader;

import ErrorFallback from "./ErrorFallback";
import type { CanvasAreaProps } from "./types";

function CanvasArea({
  isReady,
  isGenerating,
  availability,
  progress,
  canvas,
  error,
  onActivate,
  onDismissError,
}: CanvasAreaProps) {
  return (
    <main className="canvas-wrap">
      {!isReady && (
        <ErrorFallback
          availability={availability}
          progress={progress}
          error={error}
          onActivate={onActivate}
        />
      )}
      {isReady && (
        <section
          className={`generated-canvas ${isGenerating ? "is-generating" : ""}`}
          aria-live="polite"
          dangerouslySetInnerHTML={{ __html: canvas }}
        />
      )}
      {error && isReady && (
        <div className="inline-error">
          {error}{" "}
          <button type="button" onClick={onDismissError}>
            Dismiss
          </button>
        </div>
      )}
    </main>
  );
}

export default CanvasArea;

import type { ErrorFallbackProps } from "./types";

function ErrorFallback({
  availability,
  progress,
  error,
  onActivate,
}: ErrorFallbackProps) {
  return (
    <section className="ai-gate" aria-live="polite">
      <span className="eyebrow">Notice</span>
      <h2>
        {availability === "unavailable"
          ? "This website is best viewed in a browser with built-in AI."
          : availability === "downloading"
            ? "The AI model is downloading."
            : "A browser-native portfolio, still warming up."}
      </h2>
      <p>
        {availability === "unavailable"
          ? "Open this site in a supported desktop version of Chrome with Prompt API access, or check out the links in the footer."
          : "Your first visit downloads the model to your device. Nothing is sent to a remote AI service."}
      </p>
      {availability === "downloading" && (
        <div className="progress-track">
          <span style={{ width: `${Math.max(progress * 100, 4)}%` }} />
        </div>
      )}
      {availability !== "unavailable" && availability !== "downloading" && (
        <button className="primary-button" type="button" onClick={onActivate}>
          Enable local AI <span>↗</span>
        </button>
      )}
      {error && <p className="error-message">{error}</p>}
    </section>
  );
}

export default ErrorFallback;

